// public/sw.js
// Custom service worker — extends the auto-generated Workbox SW
// Handles the SKIP_WAITING message from UpdateToast.jsx so updates
// apply immediately when the user taps "Update now"

// This file is picked up by vite-plugin-pwa via the `injectManifest` strategy.
// It must import the Workbox precache manifest injection.

import { precacheAndRoute, cleanupOutdatedCaches } from "workbox-precaching";
import { clientsClaim } from "workbox-core";

// Precache all assets generated by Vite build
precacheAndRoute(self.__WB_MANIFEST);

// Clean up old caches from previous versions
cleanupOutdatedCaches();

// Listen for SKIP_WAITING message from UpdateToast.jsx
// When received, activate this SW immediately instead of waiting
// for all existing tabs to close
self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") {
    self.skipWaiting();
  }
});

// Take control of all clients as soon as this SW activates
clientsClaim();
